// SPDX-License-Identifier: MIT
/*
 * RK3576 AMP cpu3 (Cortex-A53) bare-metal validation firmware.
 *
 * Purpose: prove the whole AMP chain before RT-Thread is ported —
 *   amp partition -> U-Boot FIT load -> PSCI CPU_ON cpu3 -> runs alongside
 *   Linux (7 CPUs) without being trampled.
 *
 * Outputs:
 *   1. Heartbeat block at SHMEM_BASE (0x47c00000), pollable from Linux:
 *        devmem 0x47c00008    # counter, increments every 500ms
 *   2. Console on UART5 (GPIO3_D4/D5 = 40-pin header pins), 1500000 8N1.
 *
 * Everything runs with MMU/caches OFF (all memory Device-nGnRnE), so all
 * accesses must be naturally aligned (built with -mstrict-align).
 */

typedef unsigned int u32;
typedef unsigned long long u64;

#define UART5_BASE	0x2ad80000UL
#define CRU_BASE	0x27200000UL
#define IOC_BASE	0x26040000UL	/* ioc_grf syscon */
#define SHMEM_BASE	0x47c00000UL

#define BAUDRATE	1500000		/* 24M / 16 / 1500000 = divisor 1 (exact) */

static inline void w32(unsigned long a, u32 v)
{
	*(volatile u32 *)a = v;
}

static inline u32 r32(unsigned long a)
{
	return *(volatile u32 *)a;
}

static inline void w64(unsigned long a, u64 v)
{
	*(volatile u64 *)a = v;
}

static inline void dsb(void)
{
	__asm__ volatile("dsb sy" ::: "memory");
}

static inline u64 read_cntpct(void)
{
	u64 v;
	__asm__ volatile("isb; mrs %0, cntpct_el0" : "=r"(v));
	return v;
}

static inline u64 read_cntfrq(void)
{
	u64 v;
	__asm__ volatile("mrs %0, cntfrq_el0" : "=r"(v));
	return v;
}

static inline u64 read_mpidr(void)
{
	u64 v;
	__asm__ volatile("mrs %0, mpidr_el1" : "=r"(v));
	return v;
}

static inline u32 current_el(void)
{
	u64 v;
	__asm__ volatile("mrs %0, CurrentEL" : "=r"(v));
	return (v >> 2) & 3;
}

/* ---------------------------------------------------------------- clocks */

/* Rockchip CRU: upper 16 bits are a write-enable mask for the lower 16 */
#define RK3576_CLKSEL_CON(x)	(CRU_BASE + 0x300 + (x) * 4)
#define RK3576_CLKGATE_CON(x)	(CRU_BASE + 0x800 + (x) * 4)

static void uart5_clock_init(void)
{
	/* PCLK_UART5: CLKGATE_CON13 bit14 = 0 (ungate) */
	w32(RK3576_CLKGATE_CON(13), (1u << 14) << 16);

	/*
	 * SCLK_UART5: CLKSEL_CON64, mux[10:8] = 3 (xin24m), div[7:0] = 0 (/1)
	 * -> sclk_uart5 = 24 MHz exactly.
	 */
	w32(RK3576_CLKSEL_CON(64), ((0x7u << 8) | 0xffu) << 16 | (3u << 8));

	/* SCLK_UART5 gate: CLKGATE_CON14 bit15 = 0 (ungate) */
	w32(RK3576_CLKGATE_CON(14), (1u << 15) << 16);
}

/* ---------------------------------------------------------------- pinmux */

static void uart5_pinmux_init(void)
{
	/*
	 * GPIO3_D4 (uart5_rx_m0) / GPIO3_D5 (uart5_tx_m0) -> function 9.
	 * Bank3 iomux3 (D0-D7) at IOC + 0x4078; D4-D7 in the high register
	 * (+4): D4 = bits[3:0], D5 = bits[7:4].
	 */
	w32(IOC_BASE + 0x407c, 0x00ff0000 | (9u << 4) | 9u);

	/*
	 * Pull-up on RX (GPIO3_D4): PULL_GPIO3 = IOC + 0x6130, pin 28 ->
	 * reg +0xc, bits[9:8] = 01 (pull-up).
	 */
	w32(IOC_BASE + 0x613c, (0x3u << 8) << 16 | (0x1u << 8));
}

/* ------------------------------------------------------------------ uart */

/* DW APB UART, reg-shift = 2 */
#define UART_THR	(UART5_BASE + 0x00)
#define UART_DLL	(UART5_BASE + 0x00)
#define UART_IER	(UART5_BASE + 0x04)
#define UART_DLH	(UART5_BASE + 0x04)
#define UART_FCR	(UART5_BASE + 0x08)
#define UART_LCR	(UART5_BASE + 0x0c)
#define UART_MCR	(UART5_BASE + 0x10)
#define UART_LSR	(UART5_BASE + 0x14)
#define UART_USR	(UART5_BASE + 0x7c)
#define UART_SRR	(UART5_BASE + 0x88)

#define LSR_THRE	(1u << 5)
#define USR_BUSY	(1u << 0)

static void uart5_init(void)
{
	u32 div = 24000000 / (16 * BAUDRATE);
	int i;

	/* soft reset UART + FIFOs */
	w32(UART_SRR, 0x7);
	for (i = 0; i < 1000; i++)
		if (!(r32(UART_USR) & USR_BUSY))
			break;

	w32(UART_IER, 0);
	w32(UART_LCR, 0x83);		/* DLAB | 8n1 */
	w32(UART_DLL, div & 0xff);
	w32(UART_DLH, (div >> 8) & 0xff);
	w32(UART_LCR, 0x03);		/* 8n1 */
	w32(UART_FCR, 0x01);		/* enable FIFO */
	w32(UART_MCR, 0);
}

static void uart5_putc(char c)
{
	int i;

	for (i = 0; i < 100000; i++)
		if (r32(UART_LSR) & LSR_THRE)
			break;
	w32(UART_THR, (u32)c);
}

static void uart5_puts(const char *s)
{
	while (*s) {
		if (*s == '\n')
			uart5_putc('\r');
		uart5_putc(*s++);
	}
}

static void uart5_puthex(u64 v)
{
	static const char hex[] = "0123456789abcdef";
	int i;

	uart5_puts("0x");
	for (i = 60; i >= 0; i -= 4)
		uart5_putc(hex[(v >> i) & 0xf]);
}

static void uart5_putdec(u64 v)
{
	char buf[21];
	int i = 20;

	buf[i] = '\0';
	do {
		buf[--i] = '0' + (v % 10);
		v /= 10;
	} while (v && i > 0);
	uart5_puts(&buf[i]);
}

/* ------------------------------------------------------------- heartbeat */

/*
 * Shared heartbeat block at SHMEM_BASE (visible to Linux via devmem):
 *   +0x00 u32 magic     0x4b37414d ("K7AM" when hexdumped LE)
 *   +0x04 u32 version
 *   +0x08 u64 counter   (increments every 500 ms)
 *   +0x10 u64 cntpct    (timestamp of last beat)
 *   +0x18 u32 cntfrq
 *   +0x1c u32 current EL at boot
 */
#define HB_MAGIC	0x4b37414du

static void heartbeat(u64 counter)
{
	w64(SHMEM_BASE + 0x08, counter);
	w64(SHMEM_BASE + 0x10, read_cntpct());
	dsb();
}

static void delay_ticks(u64 ticks)
{
	u64 end = read_cntpct() + ticks;

	while (read_cntpct() < end)
		;
}

void main(void)
{
	u64 freq, half_sec, counter = 0;

	uart5_clock_init();
	uart5_pinmux_init();
	uart5_init();

	freq = read_cntfrq();
	if (!freq)
		freq = 24000000;	/* RK3576 default */
	half_sec = freq / 2;

	w32(SHMEM_BASE + 0x00, HB_MAGIC);
	w32(SHMEM_BASE + 0x04, 1);
	w32(SHMEM_BASE + 0x18, (u32)freq);
	w32(SHMEM_BASE + 0x1c, current_el());
	dsb();

	uart5_puts("\n[amp-cpu3] RK3576 KickPi K7 AMP bare-metal alive\n");
	uart5_puts("[amp-cpu3] mpidr=");
	uart5_puthex(read_mpidr());
	uart5_puts(" EL=");
	uart5_putdec(current_el());
	uart5_puts(" cntfrq=");
	uart5_putdec(freq);
	uart5_puts("\n");

	while (1) {
		heartbeat(++counter);
		if ((counter & 3) == 0) {	/* every 2s */
			uart5_puts("[amp-cpu3] heartbeat ");
			uart5_putdec(counter);
			uart5_puts("\n");
		}
		delay_ticks(half_sec);
	}
}

