/*
 * RK3576 (KickPi K7) AMP slave board definitions — cpu3 (Cortex-A53).
 */

#ifndef BOARD_H__
#define BOARD_H__

#include <rtdef.h>

extern unsigned char _start, _end;
extern unsigned char __bss_start, __bss_end;

/* ------------------------------------------------ GIC-400 (GICv2) */
#define GIC400_BASE                 0x2a700000UL
#define platform_get_gic_dist_base()   (GIC400_BASE + 0x1000)  /* GICD */
#define platform_get_gic_cpu_base()    (GIC400_BASE + 0x2000)  /* GICC */

#define ARM_GIC_MAX_NR              1
#define ARM_GIC_NR_IRQS             512
#define GIC_IRQ_START               0

/* ------------------------------------------------ UART5 (console, 40-pin) */
#define RK3576_UART5_BASE           0x2ad80000UL
#define RK3576_UART5_IRQ            113         /* GIC_SPI 81 + 32 */
#define RK3576_UART5_BAUD           1500000

/* clock & pinmux units used by drv_uart.c */
#define RK3576_CRU_BASE             0x27200000UL
#define RK3576_IOC_BASE             0x26040000UL

/* AMP interrupt priority, matches amp-irqs in the Linux DTS */
#define RK3576_AMP_IRQ_PRIO         0xd0

/* ------------------------------------------------ shared memory map */
#define AMP_PRIVATE_BASE            0x41800000UL    /* this image, 8MB */
#define AMP_PRIVATE_END             0x42000000UL
#define AMP_RPMSG_BASE              0x47800000UL    /* vring + dma pool, NC */
#define AMP_RPMSG_END               0x47c00000UL
#define AMP_SHMEM_BASE              0x47c00000UL    /* heartbeat block etc, NC */
#define AMP_SHMEM_END               0x48000000UL

void rt_hw_board_init(void);
int rt_hw_uart_init(void);

#endif /* BOARD_H__ */

/*
 * RK3576 (KickPi K7) AMP slave board init — cpu3 (Cortex-A53, MPIDR 0x3).
 *
 * This replicates the essential non-OFW parts of
 * libcpu/aarch64/common/setup.c:rt_hw_common_setup() (which is not compiled
 * when RT_USING_OFW is off): kernel aspace + heap + page pool + static MMU
 * map, then classic GIC/uart/gtimer bring-up.
 *
 * AMP-slave rules honoured here:
 *  - never touch GIC distributor-global state (RT_AMP_SLAVE in gic.c)
 *  - never call PSCI (cpu_psci.c/psci.c not built without RT_USING_OFW)
 *  - only map our own memory windows; the rest of DRAM belongs to Linux
 */

#include <rthw.h>
#include <rtthread.h>

#include <mmu.h>
#include <mm_aspace.h>
#include <mm_page.h>
#include <interrupt.h>
#include <gtimer.h>

#include "board.h"

/* referenced by libcpu when RT_USING_AMP is defined (normally provided by
 * the OFW setup code): single core, physical cpu3 of the A53 cluster */
rt_uint64_t rt_cpu_mpidr_table[RT_CPUS_NR] =
{
    0x80000003UL,   /* MPIDR_EL1 of cpu_l3 (RES1 | Aff0 = 3) */
};

static struct mem_desc platform_mem_desc[] =
{
    /* private image + heap + page pool: Normal WB cacheable */
    { AMP_PRIVATE_BASE, AMP_PRIVATE_END - 1, AMP_PRIVATE_BASE, NORMAL_MEM },

    /* rpmsg vrings + buffer pool shared with Linux: Normal non-cacheable */
    { AMP_RPMSG_BASE, AMP_RPMSG_END - 1, AMP_RPMSG_BASE, NORMAL_NOCACHE_MEM },

    /* generic shared memory (heartbeat block): Normal non-cacheable */
    { AMP_SHMEM_BASE, AMP_SHMEM_END - 1, AMP_SHMEM_BASE, NORMAL_NOCACHE_MEM },

    /* SoC peripheral window: IOC(0x26040000) CRU(0x27200000)
     * GIC(0x2a70x000) UART5(0x2ad80000) — identity Device-nGnRnE */
    { 0x26000000UL, 0x2b000000UL - 1, 0x26000000UL, DEVICE_MEM },
};

static void rt_hw_idle_wfi(void)
{
    __asm__ volatile ("wfi");
}

void rt_hw_board_init(void)
{
    rt_size_t heap_start, heap_end, page_start, page_end;
    rt_region_t init_page_region = { 0 };

    /* kernel address space: [KERNEL_ASPACE_START, ~0); ioremap window high */
    rt_hw_mmu_map_init(&rt_kernel_space, (void *)0xffffd0000000UL, 0x10000000,
                       (rt_size_t *)MMUTable, 0);

    heap_start = RT_ALIGN((rt_size_t)&_end, ARCH_PAGE_SIZE);
    heap_end   = RT_ALIGN(heap_start + ARCH_HEAP_SIZE, ARCH_PAGE_SIZE);
    page_start = heap_end;
    page_end   = RT_ALIGN(page_start + ARCH_INIT_PAGE_SIZE, ARCH_PAGE_SIZE);

    /* everything must stay inside our 8MB carve-out */
    RT_ASSERT(page_end <= AMP_PRIVATE_END);

    rt_system_heap_init((void *)heap_start, (void *)heap_end);

    init_page_region.start = page_start;
    init_page_region.end   = page_end;
    rt_page_init(init_page_region);

    /* switch from the early 1GB boot mapping to the real page table */
    rt_hw_mmu_setup(&rt_kernel_space, platform_mem_desc,
                    sizeof(platform_mem_desc) / sizeof(platform_mem_desc[0]));

    /* vectors + GICC banked init (distributor untouched: RT_AMP_SLAVE) */
    rt_hw_interrupt_init();

    /* UART5 console (also programs its CRU gates + IOC pinmux) */
    rt_hw_uart_init();
#ifdef RT_USING_CONSOLE
    rt_console_set_device(RT_CONSOLE_DEVICE_NAME);
#endif

    /* tick: ARM generic timer (CNTP, PPI 30, CNTFRQ = 24MHz on RK3576) */
    rt_hw_gtimer_init();

#ifdef RT_USING_COMPONENTS_INIT
    rt_components_board_init();
#endif

    rt_thread_idle_sethook(rt_hw_idle_wfi);
}

/*
 * RK3576 UART5 console driver (DW APB UART / 16550A compatible, reg-shift 2).
 *
 * The slave owns UART5 exclusively (Linux side: pins/clocks kept alive by the
 * rockchip-amp DTS node, IRQ 113 routed to cpu3 via amp-irqs). Since this
 * image boots BEFORE Linux, we program the CRU gates and IOC pinmux
 * ourselves (same registers as the Phase-1 bare-metal firmware).
 */

#include <rthw.h>
#include <rtthread.h>
#include <rtdevice.h>

#include <interrupt.h>
#include <gic.h>

#include "board.h"

#define UART_REG(off)   HWREG32(RK3576_UART5_BASE + ((off) << 2))

/* 16550 register indexes */
#define UART_RBR        0x00
#define UART_THR        0x00
#define UART_DLL        0x00
#define UART_IER        0x01
#define UART_DLH        0x01
#define UART_IIR        0x02
#define UART_FCR        0x02
#define UART_LCR        0x03
#define UART_MCR        0x04
#define UART_LSR        0x05
#define UART_USR        0x1f    /* DW extension: UART status register */
#define UART_SRR        0x22    /* DW extension: software reset */

#define UART_IER_ERBFI  0x01    /* RX data available irq */
#define UART_LSR_DR     0x01
#define UART_LSR_THRE   0x20
#define UART_USR_BUSY   0x01
#define UART_IIR_BUSY   0x07    /* DW busy-detect indication */

struct rk_uart
{
    struct rt_serial_device serial;
    int irq;
};

static struct rk_uart uart5;

/* ------------------------------------------------ SoC glue: CRU + IOC */

static void uart5_soc_init(void)
{
    /* PCLK_UART5 ungate: CLKGATE_CON13 bit14 = 0 (hiword-mask write) */
    HWREG32(RK3576_CRU_BASE + 0x800 + 13 * 4) = (1u << 14) << 16;

    /* SCLK_UART5 = xin24m / 1: CLKSEL_CON64 mux[10:8]=3, div[7:0]=0 */
    HWREG32(RK3576_CRU_BASE + 0x300 + 64 * 4) =
        (((0x7u << 8) | 0xffu) << 16) | (3u << 8);

    /* SCLK_UART5 ungate: CLKGATE_CON14 bit15 = 0 */
    HWREG32(RK3576_CRU_BASE + 0x800 + 14 * 4) = (1u << 15) << 16;

    /* iomux GPIO3_D4/D5 -> func9 (uart5_rx_m0/uart5_tx_m0) */
    HWREG32(RK3576_IOC_BASE + 0x407c) = 0x00ff0000 | (9u << 4) | 9u;

    /* pull-up on RX (GPIO3_D4): PULL_GPIO3 + 0xc, bits[9:8] = 01 */
    HWREG32(RK3576_IOC_BASE + 0x613c) = ((0x3u << 8) << 16) | (0x1u << 8);
}

/* ------------------------------------------------ serial ops */

static rt_err_t rk_uart_configure(struct rt_serial_device *serial,
                                  struct serial_configure *cfg)
{
    rt_uint32_t div, i;

    /* sclk_uart5 is fixed at 24MHz by uart5_soc_init() */
    div = 24000000 / (16 * cfg->baud_rate);
    if (!div)
        div = 1;

    /* soft reset UART + both FIFOs, then wait not busy */
    UART_REG(UART_SRR) = 0x7;
    for (i = 0; i < 10000 && (UART_REG(UART_USR) & UART_USR_BUSY); i++)
        ;

    UART_REG(UART_IER) = 0;
    UART_REG(UART_LCR) = 0x83;              /* DLAB | 8n1 */
    UART_REG(UART_DLL) = div & 0xff;
    UART_REG(UART_DLH) = (div >> 8) & 0xff;
    UART_REG(UART_LCR) = 0x03;              /* 8n1 */
    UART_REG(UART_FCR) = 0x01;              /* FIFO enable */
    UART_REG(UART_MCR) = 0;

    return RT_EOK;
}

static rt_err_t rk_uart_control(struct rt_serial_device *serial,
                                int cmd, void *arg)
{
    struct rk_uart *uart = serial->parent.user_data;

    switch (cmd)
    {
    case RT_DEVICE_CTRL_CLR_INT:
        UART_REG(UART_IER) &= ~UART_IER_ERBFI;
        rt_hw_interrupt_mask(uart->irq);
        break;

    case RT_DEVICE_CTRL_SET_INT:
        UART_REG(UART_IER) |= UART_IER_ERBFI;
        rt_hw_interrupt_umask(uart->irq);
        break;
    }

    return RT_EOK;
}

static int rk_uart_putc(struct rt_serial_device *serial, char c)
{
    rt_uint32_t i;

    for (i = 0; i < 500000 && !(UART_REG(UART_LSR) & UART_LSR_THRE); i++)
        rt_hw_cpu_relax();
    UART_REG(UART_THR) = (rt_uint32_t)(rt_uint8_t)c;

    return 1;
}

static int rk_uart_getc(struct rt_serial_device *serial)
{
    if (UART_REG(UART_LSR) & UART_LSR_DR)
        return (int)(UART_REG(UART_RBR) & 0xff);

    return -1;
}

static const struct rt_uart_ops rk_uart_ops =
{
    .configure = rk_uart_configure,
    .control   = rk_uart_control,
    .putc      = rk_uart_putc,
    .getc      = rk_uart_getc,
};

static void rk_uart_isr(int irqno, void *param)
{
    struct rk_uart *uart = param;
    rt_uint32_t iir = UART_REG(UART_IIR) & 0xf;

    if (iir == UART_IIR_BUSY)
    {
        /* DW busy-detect: clear by reading USR */
        (void)UART_REG(UART_USR);
        return;
    }

    if (UART_REG(UART_LSR) & UART_LSR_DR)
        rt_hw_serial_isr(&uart->serial, RT_SERIAL_EVENT_RX_IND);
}

int rt_hw_uart_init(void)
{
    struct serial_configure config = RT_SERIAL_CONFIG_DEFAULT;

    uart5_soc_init();

    config.baud_rate = RK3576_UART5_BAUD;
    uart5.irq = RK3576_UART5_IRQ;
    uart5.serial.ops = &rk_uart_ops;
    uart5.serial.config = config;

    rt_hw_serial_register(&uart5.serial, "uart5",
                          RT_DEVICE_FLAG_RDWR | RT_DEVICE_FLAG_INT_RX, &uart5);

    /* SPI 113: priority matches Linux amp-irqs (0xd0); target cpu3 is set by
     * rt_hw_interrupt_install() through RT_AMP_SLAVE_PHYS_CPU */
    rt_hw_interrupt_install(uart5.irq, rk_uart_isr, &uart5, "uart5");
    arm_gic_set_priority(0, uart5.irq, RK3576_AMP_IRQ_PRIO);

    return 0;
}

/*
 * KickPi K7 (RK3576) AMP slave application:
 *  - banner + msh console on UART5
 *  - heartbeat block at AMP_SHMEM_BASE (0x47c00000), same layout as the
 *    Phase-1 bare-metal firmware (version bumped to 2), pollable from Linux:
 *        devmem 0x47c00008     # counter, +1 every 500ms
 *  - defensive re-assert of our GIC enable bits (Linux distributor re-init
 *    can momentarily clear SPI enables during its boot)
 */

#include <rtthread.h>
#include <rthw.h>
#include <gic.h>

#include "board.h"

#define HB_MAGIC    0x4b37414du     /* "K7AM" in LE hexdump */
#define HB_VERSION  2               /* 1 = bare-metal, 2 = RT-Thread */

struct heartbeat_blk
{
    volatile rt_uint32_t magic;
    volatile rt_uint32_t version;
    volatile rt_uint64_t counter;
    volatile rt_uint64_t cntpct;
    volatile rt_uint32_t cntfrq;
    volatile rt_uint32_t el;
};

static rt_uint64_t read_cntpct(void)
{
    rt_uint64_t v;
    __asm__ volatile ("isb; mrs %0, cntpct_el0" : "=r"(v));
    return v;
}

static rt_uint64_t read_cntfrq(void)
{
    rt_uint64_t v;
    __asm__ volatile ("mrs %0, cntfrq_el0" : "=r"(v));
    return v;
}

static rt_uint32_t read_current_el(void)
{
    rt_uint64_t v;
    __asm__ volatile ("mrs %0, CurrentEL" : "=r"(v));
    return (v >> 2) & 3;
}

static void heartbeat_entry(void *param)
{
    struct heartbeat_blk *hb = (struct heartbeat_blk *)AMP_SHMEM_BASE;
    rt_uint64_t counter = 0;

    hb->magic   = HB_MAGIC;
    hb->version = HB_VERSION;
    hb->cntfrq  = (rt_uint32_t)read_cntfrq();
    hb->el      = read_current_el();

    while (1)
    {
        hb->counter = ++counter;
        hb->cntpct  = read_cntpct();
        rt_hw_dsb();

        /* defensive: our SPI enables survive Linux GIC (re)init windows */
        arm_gic_umask(0, RK3576_UART5_IRQ);

        rt_thread_mdelay(500);
    }
}

int main(void)
{
    rt_thread_t tid;
    rt_uint64_t mpidr;

    __asm__ volatile ("mrs %0, mpidr_el1" : "=r"(mpidr));

    rt_kprintf("\n[amp-cpu3] RT-Thread AMP slave on RK3576 (KickPi K7)\n");
    rt_kprintf("[amp-cpu3] mpidr=0x%lx EL%d cntfrq=%d\n",
               (unsigned long)mpidr, read_current_el(),
               (rt_uint32_t)read_cntfrq());

    tid = rt_thread_create("hbeat", heartbeat_entry, RT_NULL,
                           2048, 15, 20);
    if (tid)
        rt_thread_startup(tid);

    return 0;
}

