/*
 * RPMsg-Lite platform layer for RK3576 AMP slave (GIC softirq transport).
 * Vring geometry matches rockchip_rpmsg: 0x8000 per vring, 0x1000 align.
 */

#ifndef RPMSG_PLATFORM_H_
#define RPMSG_PLATFORM_H_

#include <stdint.h>

#ifndef VRING_ALIGN
#define VRING_ALIGN (0x1000U)
#endif

/* fixed vring stride, matches RPMSG_VRING_SIZE in rockchip_rpmsg.h */
#ifndef VRING_SIZE
#define VRING_SIZE (0x8000UL)
#endif

/* with high buffer count (64), the vrings do not fit standard computation;
 * total shared-memory overhead for one instance stays 2 vrings */
#define RL_VRING_OVERHEAD (2UL * VRING_SIZE)

#ifndef RL_PLATFORM_MAX_ISR_COUNT
#define RL_PLATFORM_MAX_ISR_COUNT (32U)
#endif

#define RL_GET_VQ_ID(link_id, queue_id) (((queue_id)&0x1U) | (((link_id) << 1U) & 0xFFFFFFFEU))
#define RL_GET_LINK_ID(id)              (((id)&0xFFFFFFFEU) >> 1U)
#define RL_GET_Q_ID(id)                 ((id)&0x1U)

#define RL_PLATFORM_USER_LINK_ID    (0U)
#define RL_PLATFORM_HIGHEST_LINK_ID (15U)

/* platform interrupt related functions */
int32_t platform_init_interrupt(uint32_t vector_id, void *isr_data);
int32_t platform_deinit_interrupt(uint32_t vector_id);
int32_t platform_interrupt_enable(uint32_t vector_id);
int32_t platform_interrupt_disable(uint32_t vector_id);
int32_t platform_in_isr(void);
void platform_notify(uint32_t vector_id);

/* platform low-level time-delay (busy loop) */
void platform_time_delay(uint32_t num_msec);

/* platform memory functions */
void platform_map_mem_region(uint32_t vrt_addr, uint32_t phy_addr, uint32_t size, uint32_t flags);
void platform_cache_all_flush_invalidate(void);
void platform_cache_disable(void);
void platform_cache_invalidate(void *data, uint32_t len);
void platform_cache_flush(void *data, uint32_t len);
uintptr_t platform_vatopa(void *addr);
void *platform_patova(uintptr_t addr);

/* platform init/deinit */
int32_t platform_init(void);
int32_t platform_deinit(void);

#endif /* RPMSG_PLATFORM_H_ */

/*
 * RPMsg-Lite platform layer: RK3576 AMP slave (cpu3) <-> Linux master,
 * transported over two reserved GIC SPIs ("rockchip,rpmsg-softirq"):
 *
 *   RX (abs 172, SPI 140): Linux irq_retrigger()s it; routed to cpu3 by the
 *       amp-irqs DTS property. One interrupt serves both vqs -> the handler
 *       pokes both queue IDs.
 *   TX (abs 173, SPI 141): we set it pending in GICD_ISPENDR; the GIC routes
 *       it to a Linux core where rockchip_rpmsg_softirq's threaded handler
 *       runs vring_interrupt(rvq).
 *
 * Shared memory is mapped Normal-NC on both sides: no cache maintenance.
 */

#include <rthw.h>
#include <rtthread.h>
#include <rtdef.h>

#include <interrupt.h>
#include <gic.h>

#include "rpmsg_config.h"
#include "rpmsg_platform.h"
#include "rpmsg_env.h"

#include "../../drivers/board.h"

static int32_t isr_counter     = 0;
static int32_t disable_counter = 0;
static void *platform_lock;

/* GICD_ISPENDR: write-1-to-set, safe concurrent access with Linux */
#define GICD_ISPENDR(n)  HWREG32(platform_get_gic_dist_base() + 0x200U + ((n) / 32U) * 4U)

static void rk_rpmsg_rx_isr(int irqno, void *param)
{
    /* single interrupt for the whole link: poke both virtqueues */
    env_isr(RL_GET_VQ_ID(RK_RPMSG_LINK_ID, 0U));
    env_isr(RL_GET_VQ_ID(RK_RPMSG_LINK_ID, 1U));
}

int32_t platform_init_interrupt(uint32_t vector_id, void *isr_data)
{
    env_lock_mutex(platform_lock);

    RL_ASSERT(0 <= isr_counter);
    env_register_isr(vector_id, isr_data);
    if (isr_counter == 0)
    {
        rt_hw_interrupt_install(RK_RPMSG_IRQ_RX, rk_rpmsg_rx_isr, RT_NULL, "rpmsg");
        arm_gic_set_priority(0, RK_RPMSG_IRQ_RX, RK3576_AMP_IRQ_PRIO);
        rt_hw_interrupt_umask(RK_RPMSG_IRQ_RX);
    }
    isr_counter++;

    env_unlock_mutex(platform_lock);

    return 0;
}

int32_t platform_deinit_interrupt(uint32_t vector_id)
{
    env_lock_mutex(platform_lock);

    RL_ASSERT(0 < isr_counter);
    isr_counter--;
    if (isr_counter == 0)
        rt_hw_interrupt_mask(RK_RPMSG_IRQ_RX);
    env_unregister_isr(vector_id);

    env_unlock_mutex(platform_lock);

    return 0;
}

void platform_notify(uint32_t vector_id)
{
    /* ensure vring updates are visible before the kick */
    rt_hw_dsb();
    GICD_ISPENDR(RK_RPMSG_IRQ_TX) = 1U << (RK_RPMSG_IRQ_TX % 32U);
    rt_hw_dsb();
}

int32_t platform_in_isr(void)
{
    return (rt_interrupt_get_nest() > 0) ? 1 : 0;
}

int32_t platform_interrupt_enable(uint32_t vector_id)
{
    RL_ASSERT(0 < disable_counter);

    disable_counter--;
    if (disable_counter == 0)
        rt_hw_interrupt_umask(RK_RPMSG_IRQ_RX);

    return (int32_t)vector_id;
}

int32_t platform_interrupt_disable(uint32_t vector_id)
{
    RL_ASSERT(0 <= disable_counter);

    if (disable_counter == 0)
        rt_hw_interrupt_mask(RK_RPMSG_IRQ_RX);
    disable_counter++;

    return (int32_t)vector_id;
}

void platform_time_delay(uint32_t num_msec)
{
    if (platform_in_isr() != 0)
    {
        rt_hw_us_delay(num_msec * 1000);
    }
    else
    {
        rt_thread_mdelay(num_msec);
    }
}

/* identity mapping, both sides use physical addresses in the descriptors */
void platform_map_mem_region(uint32_t vrt_addr, uint32_t phy_addr, uint32_t size, uint32_t flags)
{
}

/* shared memory is Normal-NC: no cache maintenance required */
void platform_cache_all_flush_invalidate(void)
{
}

void platform_cache_disable(void)
{
}

void platform_cache_invalidate(void *data, uint32_t len)
{
}

void platform_cache_flush(void *data, uint32_t len)
{
}

uintptr_t platform_vatopa(void *addr)
{
    return (uintptr_t)addr;
}

void *platform_patova(uintptr_t addr)
{
    return (void *)addr;
}

int32_t platform_init(void)
{
    if (env_create_mutex(&platform_lock, 1) != 0)
        return -1;

    return 0;
}

int32_t platform_deinit(void)
{
    env_delete_mutex(platform_lock);
    platform_lock = RT_NULL;

    return 0;
}

/*
 * rpmsg_env_bm.c allocates with libc malloc/free; route them to the
 * RT-Thread heap so no newlib sbrk syscalls are pulled in.
 */
void *malloc(size_t size)
{
    return rt_malloc(size);
}

void free(void *ptr)
{
    rt_free(ptr);
}

/*
 * RPMsg demo: announce a "rpmsg-tty" channel to Linux and echo everything.
 *
 * Linux side (CONFIG_RPMSG_TTY=y) creates /dev/ttyRPMSG0 on our name-service
 * announcement:
 *     # echo hello > /dev/ttyRPMSG0        (Linux -> RTT, echoed back)
 *     # cat /dev/ttyRPMSG0
 * RTT side:
 *     msh> rpmsg_send hi_linux             (RTT -> Linux)
 */

#include <rtthread.h>

#include "rpmsg_lite.h"
#include "rpmsg_ns.h"
#include "rpmsg_config.h"

#define RPMSG_SHMEM_BASE    0x47800000UL
#define TTY_EPT_ADDR        0x401U

static struct rpmsg_lite_instance *g_rl;
static struct rpmsg_lite_endpoint *g_ept;
static volatile uint32_t g_peer = 0xFFFFFFFFU;

static int32_t tty_ept_cb(void *payload, uint32_t payload_len, uint32_t src, void *priv)
{
    g_peer = src;

    rt_kprintf("[rpmsg] rx %d bytes from 0x%x: %.*s\n",
               (int)payload_len, (unsigned)src, (int)payload_len, (char *)payload);

    /* echo back to the sender */
    (void)rpmsg_lite_send(g_rl, g_ept, src, payload, payload_len, RL_DONT_BLOCK);

    return RL_RELEASE;
}

static void rpmsg_thread_entry(void *arg)
{
    g_rl = rpmsg_lite_remote_init((void *)RPMSG_SHMEM_BASE, RK_RPMSG_LINK_ID,
                                  RL_NO_FLAGS);
    if (g_rl == RL_NULL)
    {
        rt_kprintf("[rpmsg] remote init failed\n");
        return;
    }

    rt_kprintf("[rpmsg] remote ready, waiting for Linux master...\n");
    (void)rpmsg_lite_wait_for_link_up(g_rl, RL_BLOCK);
    rt_kprintf("[rpmsg] link up\n");

    g_ept = rpmsg_lite_create_ept(g_rl, TTY_EPT_ADDR, tty_ept_cb, RT_NULL);
    if (g_ept == RL_NULL)
    {
        rt_kprintf("[rpmsg] create ept failed\n");
        return;
    }

    (void)rpmsg_ns_announce(g_rl, g_ept, "rpmsg-tty", (uint32_t)RL_NS_CREATE);
    rt_kprintf("[rpmsg] announced 'rpmsg-tty' (ept 0x%x) -> /dev/ttyRPMSG0\n",
               TTY_EPT_ADDR);
}

static int rpmsg_app_init(void)
{
    rt_thread_t tid;

    tid = rt_thread_create("rpmsg", rpmsg_thread_entry, RT_NULL, 4096, 12, 20);
    if (tid != RT_NULL)
        rt_thread_startup(tid);

    return 0;
}
INIT_APP_EXPORT(rpmsg_app_init);

static int rpmsg_send_cmd(int argc, char **argv)
{
    if (argc < 2)
    {
        rt_kprintf("usage: rpmsg_send <text>\n");
        return -1;
    }
    if ((g_rl == RL_NULL) || (g_ept == RL_NULL))
    {
        rt_kprintf("rpmsg not ready\n");
        return -1;
    }
    if (g_peer == 0xFFFFFFFFU)
    {
        rt_kprintf("no peer yet: write /dev/ttyRPMSG0 on Linux once first\n");
        return -1;
    }

    return (int)rpmsg_lite_send(g_rl, g_ept, g_peer, argv[1],
                                (uint32_t)rt_strlen(argv[1]), 100);
}
MSH_CMD_EXPORT_ALIAS(rpmsg_send_cmd, rpmsg_send, send a string to Linux over rpmsg);

