#define DBG32(off)  (*(volatile uint32_t *)(0x47c00000UL + (off)))

static int32_t tty_ept_cb(void *payload, uint32_t payload_len, uint32_t src, void *priv)
{
    int32_t ret;

    g_peer = src;
    DBG32(0x24) = DBG32(0x24) + 1;
    DBG32(0x30) = src;

